#include "DspStageRuntime.h"
#include "TestSupport.h"
int main(){DspStageRuntime dsp;CenterSettings settings;settings.values[0]=0;settings.values[13]=1.25;std::string error;CHECK(dsp.prepareCenter(CENTER_MODULE_ROOT,settings,error));CHECK(dsp.prepareAligner(CENTER_MODULE_ROOT,error));auto s=session(1);StageBusWin32 source,out;CHECK(source.create(s,error));CHECK(dsp.attach(s,error));CHECK(out.open(dsp.outputSession(),error));Planes<10> input;Planes<11> output;
 auto cycle=[&](uint64_t seq,bool attemptWhilePending=false){for(unsigned i=0;i<1024;i++){input.data[0][i]=input.data[1][i]=double((seq-1)*1024+i+1);for(unsigned c=2;c<10;c++){uint64_t v=(i%3==0)?0x8000000000000000ULL:(i%3==1)?0x7ff8000000000000ULL+i:0x3ff0000000000000ULL+(seq*10+c);std::memcpy(&input.data[c][i],&v,8);}}auto r=request(s,seq);if(out.trySendRequest(r)!=StageBusIoResult::Ok)return false;if(dsp.step(qpc())==DspStepResult::Fault)return false;if(attemptWhilePending&&dsp.applyAlignment(false,0,0)!=AlignmentApplyResult::Busy)return false;StageBusFrameRequest up{};if(source.tryReceiveRequest(up)!=StageBusIoResult::Ok)return false;auto h=header(up);if(source.tryPublish(h,input.in.data())!=StageBusIoResult::Ok)return false;if(dsp.step(qpc())!=DspStepResult::Published)return false;StageBusBlockHeader got{};if(out.tryConsume(got,output.out.data())!=StageBusIoResult::Ok||std::memcmp(&h,&got,sizeof(h)))return false;for(unsigned c=2;c<10;c++)if(std::memcmp(input.in[c],output.in[c+1],8192))return false;return true;};
 CHECK(cycle(1));CHECK(dsp.diagnostics().alignment.valid);CHECK(dsp.diagnostics().alignment.mode==0);CHECK(dsp.diagnostics().alignment.proposed[0]==240);CHECK(!std::memcmp(input.in[0],output.in[0],8192));auto revision=dsp.diagnostics().center.revision;CHECK(dsp.applyAlignment(true,revision,240)==AlignmentApplyResult::Applied);auto generation=dsp.diagnostics().alignment.generation;CHECK(dsp.diagnostics().alignment.current[0]==240);CHECK(cycle(2,true));for(unsigned i=0;i<1024;i++){CHECK(output.data[0][i]==(i<240?0.0:double(1024+i+1-240)));if(i>=240)CHECK(output.data[0][i]==output.data[2][i]);}
 settings.values[13]=2.5;CHECK(dsp.applyCenter(settings,revision+1));CHECK(dsp.applyAlignment(true,revision,240)==AlignmentApplyResult::Stale);CHECK(cycle(3));CHECK(dsp.diagnostics().alignment.proposed[0]==480);CHECK(dsp.diagnostics().alignment.current[0]==240 && dsp.diagnostics().alignment.generation==generation);CHECK(dsp.applyAlignment(true,revision+1,480)==AlignmentApplyResult::Applied);CHECK(cycle(4));for(unsigned i=480;i<1024;i++)CHECK(output.data[0][i]==output.data[2][i]);CHECK(dsp.applyAlignment(false,0,0)==AlignmentApplyResult::Applied);CHECK(cycle(5));CHECK(!std::memcmp(input.in[0],output.in[0],8192));CHECK(!std::memcmp(input.in[1],output.in[1],8192));CHECK(dsp.diagnostics().alignment.mode==0 && dsp.diagnostics().alignment.current[0]==0);
 std::cout<<"PASS real StageBus: startup exact bypass, manual C240 alignment, no auto-update for C480, stale/pending refusal, local generations, exact Cinema and source headers, explicit bypass\n";}
